const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Northern Tablelands, New South Wales, Australia.
  // Using a bounding box for the general region.
  const geometry = ee.Geometry.Rectangle([150.0, -32.0, 153.0, -28.5]);
  const date = '2025-08-02';
  const scale = 1000; // Use a reasonable scale to avoid memory issues for region reduction

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(geometry);

  // Check if collection is empty
  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No Sentinel-2 SR images found for 2025-08-02 in the Northern Tablelands.");
    // Try fallback to Level-1C if SR is empty. Clouds will be identified differently.
    // For this specific question, if SR is empty, we likely don't have enough info.
    // Given it's a future date, it's possible the collection is not yet populated.
    console.log("Attempting fallback to Sentinel-2 Level-1C.");
    collection = ee.ImageCollection('COPERNICUS/S2')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(geometry);
    const fallbackCollectionSize = await collection.size().getInfo();
    if (fallbackCollectionSize === 0) {
      console.log("No Sentinel-2 Level-1C images found for 2025-08-02 either.");
      console.log("C1");
      return;
    }
    console.log(`Found ${fallbackCollectionSize} Level-1C images.`);
    console.log("Warning: Using Level-1C, cloud/snow detection might be less precise.");
  } else {
    console.log(`Found ${collectionSize} Sentinel-2 SR images.`);
  }

  // Get the first image, assuming one image per day covers the region, or we take the first available.
  const image = ee.Image(collection.first());
  if (!image) { // This should ideally be caught by collectionSize check, but good for robustness
    console.log("No image found after filtering.");
    console.log("C1");
    return;
  }

  // 3. Processing
  // Sentinel-2 QA60 band bits:
  // Bit 10: Opaque clouds
  // Bit 11: Cirrus clouds
  // Bit 8: Cloud shadows (not directly used for cloud presence)
  // Bit 9: Snow / Ice (for SR products, this is less reliable than NDSI for snow extent)
  const qa60 = image.select('QA60');

  // Cloud mask: 1 if cloudy, 0 if not
  const cloudMask = qa60.bitwiseAnd(1 << 10).eq(0).and(qa60.bitwiseAnd(1 << 11).eq(0));

  // Compute NDSI for snow detection
  // NDSI = (Green - SWIR1) / (Green + SWIR1)
  // Green = B3, SWIR1 = B11 for Sentinel-2
  const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
  // Snow mask: NDSI > 0.2 and B8 (NIR) > 0.1 (often used to distinguish from water/dark soil)
  // Also, a high reflectance in the green band (B3 > 0.1) can help.
  const snowMask = ndsi.gt(0.2).and(image.select('B8').gt(0.1));

  // Combine masks: snow-only mask (areas with snow AND no clouds)
  const snowOnly = snowMask.and(cloudMask);

  // Count pixels
  const totalPixels = image.mask(cloudMask).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('B2'); // Use a common band like B2 to count valid non-cloudy pixels

  const snowPixels = snowOnly.reduceRegion({
    reducer: ee.Reducer.sum(), // Sum of 1s in snowOnly mask
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDSI'); // Use NDSI band for sum after applying snowOnly mask

  const cloudPixels = qa60.bitwiseAnd(1 << 10).gt(0).or(qa60.bitwiseAnd(1 << 11).gt(0)).reduceRegion({
    reducer: ee.Reducer.sum(), // Sum of 1s for cloudy pixels
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('QA60');

  // Fetch results
  const totalPxVal = await totalPixels.getInfo();
  const snowPxVal = await snowPixels.getInfo();
  const cloudPxVal = await cloudPixels.getInfo();

  // 4. Validation & Final Answer
  if (totalPxVal === 0 || totalPxVal === null) {
    console.log("No valid pixels after initial cloud masking or processing.");
    console.log("C2");
    return;
  }
  if (snowPxVal === null || cloudPxVal === null) {
    console.log("Calculation resulted in null for snow or cloud pixels.");
    console.log("C3");
    return;
  }

  console.log(`Total valid non-cloudy pixels: ${totalPxVal}`);
  console.log(`Snow pixels detected (NDSI>0.2 & NIR>0.1, no clouds): ${snowPxVal}`);
  console.log(`Cloudy pixels detected (QA60 bits 10/11): ${cloudPxVal}`);

  // The question: 'Was there only snow and no clouds present'
  // This implies:
  // 1. There MUST be snow (snowPxVal > 0)
  // 2. There MUST be NO clouds (cloudPxVal is 0 or negligible)

  const hasSnow = snowPxVal > 0;
  const hasNoClouds = cloudPxVal === 0; // Strict interpretation of "no clouds"

  if (hasSnow && hasNoClouds) {
    console.log("A"); // Yes, only snow and no clouds were present.
  } else {
    console.log("B"); // No, either no snow, or clouds were present.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
